+using System.Text.RegularExpressions;
+
+namespace DocSummary.Services;
+
+public partial class DocumentSummarizer
+{
+    private static readonly HashSet<string> StopWords =
+    [
+        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
+        "in", "on", "at", "to", "for", "of", "with", "by", "it", "this",
+        "that", "from", "as", "be", "has", "have", "had", "do", "does",
+        "did", "will", "would", "could", "should", "may", "might", "not",
+        "no", "so", "if", "then", "than", "too", "very", "can", "just",
+        "about", "into", "over", "after", "before", "between", "under",
+        "such", "each", "which", "their", "its", "also", "been", "being",
+        "more", "some", "other", "there", "these", "those", "them", "they",
+        "he", "she", "we", "you", "i", "me", "my", "your", "his", "her"
+    ];
+
+    [GeneratedRegex(@"(?<=[.!?])\s+")]
+    private static partial Regex SentenceSplitter();
+
+    [GeneratedRegex(@"[^a-zA-Z0-9\s]")]
+    private static partial Regex Punctuation();
+
+    /// <summary>
+    /// Produces an extractive summary by scoring sentences based on word frequency
+    /// and returning the top-ranked sentences in their original order.
+    /// </summary>
+    public string Summarize(string text, int maxSentences)
+    {
+        if (string.IsNullOrWhiteSpace(text))
+            return string.Empty;
+
+        var sentences = SentenceSplitter()
+            .Split(text)
+            .Select(s => s.Trim())
+            .Where(s => s.Length > 0)
+            .ToList();
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        var wordFrequencies = BuildWordFrequencies(sentences);
+        var scored = sentences
+            .Select((sentence, index) => (Index: index, Score: ScoreSentence(sentence, wordFrequencies)))
+            .OrderByDescending(x => x.Score)
+            .Take(maxSentences)
+            .OrderBy(x => x.Index) // preserve original order
+            .Select(x => sentences[x.Index]);
+
+        return string.Join(" ", scored);
+    }
+
+    private static Dictionary<string, int> BuildWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in GetWords(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    freq[word] = freq.GetValueOrDefault(word) + 1;
+            }
+        }
+        return freq;
+    }
+
+    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
+    {
+        var words = GetWords(sentence);
+        if (words.Length == 0) return 0;
+
+        double score = words
+            .Where(w => !StopWords.Contains(w))
+            .Sum(w => wordFrequencies.GetValueOrDefault(w));
+
+        // Normalize by word count to avoid biasing toward long sentences
+        return score / words.Length;
+    }
+
+    private static string[] GetWords(string text) =>
+        Punctuation().Replace(text, "")
+            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
+            .Select(w => w.ToLowerInvariant())
+            .ToArray();
+}
